@using sv_bd55516a6d034caf8512fd8b5c880e7b.Services
@inject ISettingsService SettingsService

<section class="notifications-section">
    <h2>Notifications</h2>

    @if (isLoading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="emailNotifications" />
                    <span class="toggle-switch"></span>
                    <span class="toggle-label">Email Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="pushNotifications" />
                    <span class="toggle-switch"></span>
                    <span class="toggle-label">Push Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="weeklyDigest" />
                    <span class="toggle-switch"></span>
                    <span class="toggle-label">Weekly Digest</span>
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                <p class="channels-description">Select channels to mute notifications from:</p>
                <div class="channels-list">
                    @foreach (var channel in availableChannels)
                    {
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (!string.IsNullOrEmpty(message))
            {
                <div class="toast @messageType">@message</div>
            }
        </div>
    }
</section>

@code {
    private bool isLoading = true;
    private bool isSaving;
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private string? message;
    private string messageType = "success";

    private readonly List<string> availableChannels = new()
    {
        "General", "Announcements", "Engineering", "Marketing", "Support", "Random"
    };

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        try
        {
            var prefs = await SettingsService.GetNotificationPrefsAsync();
            emailNotifications = prefs.EmailNotifications;
            pushNotifications = prefs.PushNotifications;
            weeklyDigest = prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(prefs.MutedChannels);
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        message = null;
        try
        {
            var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            message = "Preferences saved successfully!";
            messageType = "success";
        }
        catch (Exception ex)
        {
            message = $"Failed to save: {ex.Message}";
            messageType = "error";
        }
        finally
        {
            isSaving = false;
        }
    }
}

.notifications-section h2 {
    margin-bottom: 1.5rem;
    color: #333;
}

.notifications-form {
    max-width: 600px;
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 2rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    padding: 0.75rem 1rem;
    border-radius: 8px;
    background: #f8f9fa;
    transition: background 0.15s;
}

.toggle-item:hover {
    background: #e9ecef;
}

.toggle-item input[type="checkbox"] {
    width: 40px;
    height: 20px;
    appearance: none;
    background: #ccc;
    border-radius: 10px;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
    flex-shrink: 0;
}

.toggle-item input[type="checkbox"]::after {
    content: '';
    position: absolute;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: white;
    top: 2px;
    left: 2px;
    transition: transform 0.2s;
}

.toggle-item input[type="checkbox"]:checked {
    background: #1976d2;
}

.toggle-item input[type="checkbox"]:checked::after {
    transform: translateX(20px);
}

.toggle-label {
    font-size: 0.95rem;
    font-weight: 500;
}

.channels-section {
    margin-bottom: 1.5rem;
}

.channels-section h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
    color: #333;
}

.channels-description {
    font-size: 0.875rem;
    color: #666;
    margin-bottom: 0.75rem;
}

.channels-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f0f0f0;
}

.form-actions {
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast.error {
    background: #fbe9e7;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #666;
    font-style: italic;
}

@using sv_bd55516a6d034caf8512fd8b5c880e7b.Services
@inject ISettingsService SettingsService

<section class="security-section">
    <h2>Security</h2>

    @if (isLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="panel-toggle">@(passwordPanelOpen ? "▲" : "▼")</span>
            </button>

            @if (passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                    @if (!string.IsNullOrEmpty(passwordMessage))
                    {
                        <div class="toast @passwordMessageType">@passwordMessage</div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <div class="twofa-header">
                <div>
                    <h3>Two-Factor Authentication</h3>
                    <p class="twofa-status">
                        Status:
                        <span class="status-badge @(twoFactorEnabled ? "enabled" : "disabled")">
                            @(twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </p>
                </div>
                <label class="toggle-item">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span class="toggle-switch"></span>
                </label>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            @if (sessions.Any())
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != sessions.First())
                                    {
                                        <button class="btn btn-danger btn-sm"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
            else
            {
                <p>No active sessions found.</p>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@isRevoking">
                            @(isRevoking ? "Revoking..." : "Revoke")
                        </button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</section>

@code {
    private bool isLoading = true;
    private bool passwordPanelOpen;
    private bool isChangingPassword;
    private bool isRevoking;
    private bool twoFactorEnabled;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordMessage;
    private string passwordMessageType = "success";
    private List<ActiveSession> sessions = new();
    private ActiveSession? sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        try
        {
            var settings = await SettingsService.GetSecuritySettingsAsync();
            twoFactorEnabled = settings.TwoFactorEnabled;
            sessions = settings.Sessions;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdatePassword()
    {
        passwordMessage = null;
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordMessage = "Please fill in all password fields.";
            passwordMessageType = "error";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordMessage = "New password and confirmation do not match.";
            passwordMessageType = "error";
            return;
        }

        isChangingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordMessage = "Password updated successfully!";
            passwordMessageType = "success";
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordMessage = $"Failed to change password: {ex.Message}";
            passwordMessageType = "error";
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is null) return;

        isRevoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            sessions.Remove(sessionToRevoke);
            sessionToRevoke = null;
        }
        catch (Exception)
        {
            // Keep dialog open on failure
        }
        finally
        {
            isRevoking = false;
        }
    }
}

