                <div class="radio-group">
                    @foreach (var themeOption in themeOptions)
                    {
                        <label class="radio-item @(theme == themeOption ? "selected" : "")">
                            <input type="radio" name="theme" value="@themeOption"
                                   checked="@(theme == themeOption)"
                                   @onchange="() => theme = themeOption" />
                            <span class="radio-label">@themeOption</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="setting-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var sizeOption in fontSizeOptions)
                    {
                        <label class="radio-item @(fontSize == sizeOption ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@sizeOption"
                                   checked="@(fontSize == sizeOption)"
                                   @onchange="() => fontSize = sizeOption" />
                            <span class="radio-label">@sizeOption</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="setting-group">
                <h3>Language</h3>
                <select class="language-select" @bind="language">
                    @foreach (var lang in languageOptions)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="setting-group">
                <h3>Compact Mode</h3>
                <label class="toggle-item">
                    <input type="checkbox" @bind="compactMode" />
                    <span class="toggle-switch"></span>
                    <span class="toggle-label">Enable compact mode for denser UI layout</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="setting-group">
                <h3>Preview</h3>
                <div class="preview-area @GetPreviewClasses()">
                    <div class="preview-header">Sample Header</div>
