{"file_text": "@using sv_bd55516a6d034caf8512fd8b5c880e7b.Services
@inject ISettingsService SettingsService

<section class="appearance-section">
    <h2>Appearance</h2>

    @if (isLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="setting-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var themeOption in themeOptions)
                    {
                        <label class="radio-item @(theme == themeOption ? "selected" : "")">
                            <input type="radio" name="theme" value="@themeOption"
                                   checked="@(theme == themeOption)"
                                   @onchange="() => theme = themeOption" />
                            <span class="radio-label">@themeOption</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="setting-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var sizeOption in fontSizeOptions)
                    {
                        <label class="radio-item @(fontSize == sizeOption ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@sizeOption"
                                   checked="@(fontSize == sizeOption)"
                                   @onchange="() => fontSize = sizeOption" />
                            <span class="radio-label">@sizeOption</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="setting-group">
                <h3>Language</h3>
                <select class="language-select" @bind="language">
                    @foreach (var lang in languageOptions)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="setting-group">
                <h3>Compact Mode</h3>
                <label class="toggle-item">
                    <input type="checkbox" @bind="compactMode" />
                    <span class="toggle-switch"></span>
                    <span class="toggle-label">Enable compact mode for denser UI layout</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="setting-group">
                <h3>Preview</h3>
                <div class="preview-area @GetPreviewClasses()">
                    <div class="preview-header">Sample Header</div>
                    <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                    <div class="preview-card">
                        <span class="preview-card-title">Card Title</span>
                        <span class="preview-card-body">Card content preview</span>
                    </div>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save")
                </button>
            </div>

            @if (!string.IsNullOrEmpty(message))
            {
                <div class="toast @messageType">@message</div>
            }
        </div>
    }
</section>

@code {
    private bool isLoading = true;
    private bool isSaving;
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private string? message;
    private string messageType = "success";

    private readonly string[] themeOptions = { "Light", "Dark", "System" };
    private readonly string[] fontSizeOptions = { "Small", "Medium", "Large" };
    private readonly string[] languageOptions = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            theme = settings.Theme;
            fontSize = settings.FontSize;
            language = settings.Language;
            compactMode = settings.CompactMode;
        }
        finally
        {
            isLoading = false;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"theme-{theme.ToLowerInvariant()}");
        classes.Add($"font-{fontSize.ToLowerInvariant()}");
        if (compactMode) classes.Add("compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        message = null;
        try
        {
            var settings = new AppearanceSettings(theme, fontSize, language, compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            message = "Appearance settings saved!";
            messageType = "success";
        }
        catch (Exception ex)
        {
            message = $"Failed to save: {ex.Message}";
            messageType = "error";
        }
        finally
        {
            isSaving = false;
        }
    }
}
