toolArgs.file_text:
.notifications-section h2 {
    margin-bottom: 1.5rem;
    color: #333;
}

.notifications-form {
    max-width: 600px;
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 2rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    padding: 0.75rem 1rem;
    border-radius: 8px;
    background: #f8f9fa;
    transition: background 0.15s;
}

.toggle-item:hover {
    background: #e9ecef;
}

.toggle-item input[type="checkbox"] {
    width: 40px;
    height: 20px;
    appearance: none;
    background: #ccc;
    border-radius: 10px;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
    flex-shrink: 0;
}

.toggle-item input[type="checkbox"]::after {
    content: '';
    position: absolute;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: white;
    top: 2px;
    left: 2px;
    transition: transform 0.2s;
}

.toggle-item input[type="checkbox"]:checked {
    background: #1976d2;
}

.toggle-item input[type="checkbox"]:checked::after {
    transform: translateX(20px);
}

.toggle-label {
    font-size: 0.95rem;
    font-weight: 500;
}

.channels-section {
    margin-bottom: 1.5rem;
}

.channels-section h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
    color: #333;
}

.channels-description {
    font-size: 0.875rem;
    color: #666;
    margin-bottom: 0.75rem;
}

.channels-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f0f0f0;
}

.form-actions {
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

.btn-primary {
    background: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast.error {
    background: #fbe9e7;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #666;
    font-style: italic;
}

