.appearance-section h2 {
    margin-bottom: 1.5rem;
    color: #333;
}

.appearance-form {
    max-width: 600px;
}

.setting-group {
    margin-bottom: 1.75rem;
}

.setting-group h3 {
    font-size: 1rem;
    margin-bottom: 0.75rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;
