.radio-item:hover {
    border-color: #90caf9;
}

.radio-item.selected {
    border-color: #1976d2;
    background: #e3f2fd;
}

.radio-item input[type="radio"] {
    display: none;
}

.radio-label {
    font-size: 0.9rem;
    font-weight: 500;
}

.language-select {
    padding: 0.5rem 1rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 40px;
    height: 20px;
    appearance: none;
    background: #ccc;
    border-radius: 10px;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
    flex-shrink: 0;
}

.toggle-item input[type="checkbox"]::after {
    content: '';
    position: absolute;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: white;
    top: 2px;
    left: 2px;
    transition: transform 0.2s;
}

.toggle-item input[type="checkbox"]:checked {
    background: #1976d2;
}

.toggle-item input[type="checkbox"]:checked::after {
    transform: translateX(20px);
}

.toggle-label {
    font-size: 0.9rem;
    color: #555;
}

